// Persistent virtual-estimator state (context survives across ticks; msg does not).
// Instead of independent random draws each second, we random-walk a single
// "load" scalar (0-1, how hard the pump is working) with mean reversion, plus
// occasional FAULT/STOPPED episodes. All 6 metrics are derived FROM load
// (+ a fault-severity ramp), so they move together the way real pump
// telemetry does, instead of jumping to unrelated random numbers every tick.

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function jitter(scale) { return (Math.random() - 0.5) * 2 * scale; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function step(current, target, speed, noise) { return current + speed * (target - current) + jitter(noise); }

let state = context.get('state');
if (!state) {
    state = { load: 0.5, regime: 'RUNNING', regimeTicksLeft: 0, regimeTotalTicks: 0, faultSeverity: 0 };
}

// Regime transitions: mostly RUNNING, with rare FAULT / STOPPED episodes.
if (state.regimeTicksLeft > 0) {
    state.regimeTicksLeft--;
    if (state.regimeTicksLeft === 0) {
        state.regime = 'RUNNING';
        state.faultSeverity = 0;
    }
} else if (state.regime === 'RUNNING') {
    if (Math.random() < 0.003) {
        state.regime = 'FAULT';
        state.regimeTotalTicks = randInt(15, 40);
        state.regimeTicksLeft = state.regimeTotalTicks;
    } else if (Math.random() < 0.002) {
        state.regime = 'STOPPED';
        state.regimeTotalTicks = randInt(20, 60);
        state.regimeTicksLeft = state.regimeTotalTicks;
    }
}

// Fault severity ramps 0 -> ~1 across the episode, then resets on recovery.
if (state.regime === 'FAULT') {
    state.faultSeverity = 1 - (state.regimeTicksLeft / state.regimeTotalTicks);
}

// "load" = how hard the pump is working (0-1). Random-walks with mean
// reversion toward a regime-specific target, so it drifts smoothly instead
// of teleporting -- this is what gives every metric real momentum/trend.
const loadTarget = state.regime === 'STOPPED' ? 0.02 : 0.5;
const loadSpeed  = state.regime === 'STOPPED' ? 0.35 : 0.06;
const loadNoise  = state.regime === 'STOPPED' ? 0.02 : 0.05;
state.load = clamp(step(state.load, loadTarget, loadSpeed, loadNoise), 0.02, 1);

// Noise gets louder as fault severity rises (heteroscedastic measurement noise).
const noiseScale = 1 + state.faultSeverity * 2;
const load = state.load;
const fault = state.faultSeverity;

function round1(v) { return Math.round(v * 10) / 10; }

msg.payload = {
    flowRate:          round1(clamp(50   + load * 250 - fault * 80  + jitter(6    * noiseScale), 50,   300)),
    rpm:               round1(clamp(1000 + load * 2600              + jitter(30   * noiseScale), 1000, 3600)),
    vibration:         round1(clamp(0.5  + load * 4   + fault * 6   + jitter(0.4  * noiseScale), 0.5,  12)),
    suctionPressure:   round1(clamp(3    - load * 2.5 + fault * 0.3 + jitter(0.08 * noiseScale), 0.5,  3)),
    dischargePressure: round1(clamp(2    + load * 10  - fault * 3   + jitter(0.3  * noiseScale), 2,    12)),
    motorTemp:         round1(clamp(20   + load * 40  + fault * 25  + jitter(1.5  * noiseScale), 20,   90)),
    status:            state.regime,
    timestamp:         new Date().toISOString()
};

context.set('state', state);

// Tell the backend the body is JSON so Express parses it correctly.
msg.headers = { "Content-Type": "application/json" };

return msg;
